view.innerHTML='<div class="v3-head"><strong>VIGIL // 3D BATHYMETRY &amp; UUV PILOTING</strong><button type="button" id="v3-close">RETURN TO SIMULATION BAY</button></div><div class="v3-meta"><span id="v3-depth">DEPTH —</span><span id="v3-heading">HEADING —</span><span id="v3-speed">SPEED —</span><span id="v3-survey">SURVEY LINK: LIVE</span></div><canvas id="vigil-3d-terrain" aria-label="First-person underwater view with rotating sonar sweep"></canvas><div id="v3-terrain-resizer" class="v3-terrain-resizer" role="separator" aria-orientation="horizontal" tabindex="0" aria-label="Resize the FPS 3D terrain view using the mouse or up and down arrow keys"></div><div class="v3-fps-compass" aria-label="Scrolling first-person compass tape"><div class="v3-fps-compass-readout"><span id="v3-fps-bearing">000°</span><span id="v3-fps-cardinal">N</span></div><div class="v3-fps-compass-window"><div id="v3-fps-compass-track" class="v3-fps-compass-track"></div><div class="v3-fps-compass-pointer"></div></div></div><section class="v3-world-map" id="v3-world-map-panel" aria-label="Unified seafloor sensor map"><div class="v3-world-map-head"><strong id="v3-world-map-title">LOCAL MAP</strong><div class="v3-map-actions"><button type="button" id="v3-map-layer" title="Highlight a sensor layer while keeping all layers active">FUSED</button><button type="button" id="v3-map-expand" aria-expanded="false">EXPAND MAP</button></div></div><div class="v3-world-map-modes"><button type="button" id="v3-map-local" aria-pressed="true">LOCAL</button><button type="button" id="v3-map-regional" aria-pressed="false">REGIONAL</button></div><div class="v3-world-map-fusion"><strong>FUSED SENSOR LAYERS</strong><span>MBES · SIDE-SCAN · SUB-BOTTOM · MAG · CTD · THERMAL · IR · DVL</span><span id="v3-map-rift-status">CRUSTAL ANOMALY // SEARCHING</span></div><canvas id="vigil-3d-world-map-canvas" aria-label="Unified seafloor map with simultaneous multibeam, side-scan, sub-bottom, magnetic, CTD, thermal, infrared-feed, DVL and registered sensor overlays"></canvas><div class="v3-world-map-legend"><span class="v3-map-ground-key">■ LAND</span><span class="v3-map-shallow-key">■ SHALLOW</span><span class="v3-map-deep-key">■ DEEP WATER</span><span class="v3-map-trench-key">■ TRENCH</span><span class="v3-map-own">● VIGIL UNITS</span><span class="v3-map-contact">● CONTACTS</span><span class="v3-map-rift">◇ RIFT / 24.5 KM</span></div><div class="v3-map-footnote">WORLD MODEL + REGISTERED SENSOR INPUTS // ALL MODALITY OVERLAYS ACTIVE TOGETHER</div></section><section class="v3-helm" aria-label="Navigation helm"><div class="v3-heading-panel"><div class="v3-heading-instrument" role="group" aria-label="Live course compass"><div class="v3-heading-dial" role="img" aria-label="Compass with ordered course and actual heading needles"><svg viewBox="0 0 132 132" aria-hidden="true"><circle cx="66" cy="66" r="61" fill="#010604" stroke="#397b58" stroke-width="1.5"/><circle cx="66" cy="66" r="52" fill="none" stroke="#164d36" stroke-width="1"/><circle cx="66" cy="66" r="37" fill="none" stroke="#103b2b" stroke-width="1" stroke-dasharray="2 4"/><path d="M66 8V20 M66 112V124 M8 66H20 M112 66H124 M25 25L34 34 M98 98L107 107 M107 25L98 34 M34 98L25 107" stroke="#398565" stroke-width="1.4"/><text x="66" y="15" fill="#d8ffe9" font-size="10" font-weight="bold" text-anchor="middle">N</text><text x="119" y="69" fill="#8dceb0" font-size="9" text-anchor="middle">E</text><text x="66" y="126" fill="#8dceb0" font-size="9" text-anchor="middle">S</text><text x="13" y="69" fill="#8dceb0" font-size="9" text-anchor="middle">W</text><g id="v3-actual-needle" transform="rotate(0 66 66)"><path d="M66 25 L61 68 L66 63 L71 68 Z" fill="#62b8ff" stroke="#d5f0ff" stroke-width=".7"/><path d="M66 107 L61 68 L66 73 L71 68 Z" fill="#205e88"/></g><g id="v3-course-needle" transform="rotate(0 66 66)"><path d="M66 20 L58 68 L66 62 L74 68 Z" fill="#29f5b2" stroke="#c4ffeb" stroke-width=".7"/><path d="M66 112 L58 68 L66 74 L74 68 Z" fill="#155740"/></g><circle cx="66" cy="66" r="4.5" fill="#020907" stroke="#e1fff3" stroke-width="1.5"/><circle cx="66" cy="66" r="1.5" fill="#29f5b2"/></svg></div><div class="v3-heading-values"><span class="v3-heading-label">ORDERED COURSE</span><strong id="v3-course-bearing" class="v3-course-bearing">000°</strong><span id="v3-course-cardinal" class="v3-course-cardinal">NORTH</span><div class="v3-actual-readout"><span>ACTUAL HEADING</span><strong id="v3-actual-bearing">---°</strong></div></div></div><div class="v3-course-editor"><label for="v3-course">SET COURSE / HEADING (000–359°)</label><div class="v3-course-row"><input id="v3-course" type="number" min="0" max="359" step="1" value="0" inputmode="numeric"><button type="button" id="v3-set-course">SET COURSE</button></div></div></div><div class="v3-compass" aria-label="Quick course adjustment"><button type="button" data-course-offset="-15">−15°</button><button type="button" data-course-offset="15">+15°</button><button type="button" data-course-offset="0" id="v3-course-north">N 000°</button><button type="button" data-course-offset="0" id="v3-course-hold">HOLD</button></div></section><section class="v3-panel" aria-label="Vehicle movement controls"><h3 class="v3-panel-title">HELM // MANEUVERING</h3><div class="v3-controls"><button data-move="left">TURN LEFT</button><button data-move="right">TURN RIGHT</button><button data-move="up">ASCEND</button><button data-move="down">DESCEND</button><button data-move="slower">SPEED −</button><button data-move="faster">SPEED +</button></div></section><details class="v3-panel v3-collapsible" aria-label="Sensor and view controls"><summary class="v3-panel-title">SENSORS // DISPLAY</summary><div class="v3-controls"><button id="v3-scan" class="v3-primary">START / PAUSE SURVEY</button><button id="v3-spawn">SPAWN AREA</button><button id="v3-zoomout">ZOOM −</button><button id="v3-zoomin">ZOOM +</button><button id="v3-reset">RESET VIEW</button></div></details><details class="v3-panel v3-collapsible" id="v3-arm-panel" aria-label="Dual robotic arm fabrication controls"><summary class="v3-panel-title">SUBSEA FABRICATION // DUAL ARM CONTROL</summary><p class="v3-gamepad-help">UUV-01 SIMULATED ACTUATORS AND TELEMETRY // TWO INDEPENDENT ARMS. ARM 1 COMBINES THE THREE-PRONG LASER/CHISEL; ARM 2 CARRIES THE COMPACT DIAMOND CIRCULAR SAW.</p><section style="border:1px solid #245b40;padding:8px;margin:7px 0;background:#020907"><h4 style="margin:0 0 7px;color:#9de7ba;font-size:10px">ARM 1 // THREE-PRONG LASER / CHISEL</h4><div class="v3-controls"><button id="v3-arm1-deploy" class="v3-primary">DEPLOY ARM 1</button><button id="v3-arm1-extend">EXTEND</button><button id="v3-arm1-retract">RETRACT</button><button id="v3-arm1-left">WRIST LEFT</button><button id="v3-arm1-right">WRIST RIGHT</button><button id="v3-arm1-prongs">OPEN PRONGS</button><button id="v3-arm1-grip">GRIP / RELEASE</button><button id="v3-arm1-laser">LASER ENABLE</button><button id="v3-arm1-weld">WELD MODE</button></div><div id="v3-arm1-status" role="status" style="margin-top:7px;color:#9de7ba;font-size:10px">ARM 1 STOWED // CHISEL CLOSED // LASER SAFE</div><div style="display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:5px;margin-top:7px"><div class="sensor-metric"><b id="v3-arm1-extension-read">0%</b><span>EXTENSION</span></div><div class="sensor-metric"><b id="v3-arm1-joint-read">0°</b><span>WRIST</span></div><div class="sensor-metric"><b id="v3-arm1-temp-read">18°C</b><span>EMITTER TEMP</span></div><div class="sensor-metric"><b id="v3-arm1-grip-read">0%</b><span>GRIP LOAD</span></div></div></section><section style="border:1px solid #245b40;padding:8px;margin:7px 0;background:#020907"><h4 style="margin:0 0 7px;color:#9de7ba;font-size:10px">ARM 2 // COMPACT DIAMOND CIRCULAR SAW</h4><div class="v3-controls"><button id="v3-arm2-deploy" class="v3-primary">DEPLOY ARM 2</button><button id="v3-arm2-extend">EXTEND</button><button id="v3-arm2-retract">RETRACT</button><button id="v3-arm2-left">WRIST LEFT</button><button id="v3-arm2-right">WRIST RIGHT</button><button id="v3-arm2-stabilize">CONTACT SHOE</button><button id="v3-arm2-saw">SAW MOTOR ON</button><button id="v3-arm2-speed">BLADE SPEED +</button></div><div id="v3-arm2-status" role="status" style="margin-top:7px;color:#9de7ba;font-size:10px">ARM 2 STOWED // SAW OFF // CONTACT SHOE RETRACTED</div><div style="display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:5px;margin-top:7px"><div class="sensor-metric"><b id="v3-arm2-extension-read">0%</b><span>EXTENSION</span></div><div class="sensor-metric"><b id="v3-arm2-rpm-read">0</b><span>BLADE RPM</span></div><div class="sensor-metric"><b id="v3-arm2-load-read">0%</b><span>MOTOR LOAD</span></div><div class="sensor-metric"><b id="v3-arm2-vibe-read">0.02</b><span>VIBRATION</span></div></div></section><div id="v3-arm-system-status" role="status" style="color:#9de7ba;font-size:10px;padding:5px 0">ARM TELEMETRY // SIMULATION SOURCE // NO PHYSICAL HARDWARE CONNECTED</div></details><details class="v3-panel v3-collapsible" id="v3-gamepad-panel" aria-label="Gamepad controller mapping"><summary class="v3-panel-title">GAMEPAD // CONTROLLER MAPPING</summary><div class="v3-gamepad-toolbar"><span id="v3-gamepad-status" role="status">CONNECT A CONTROLLER // THEN MAP ANY ACTION</span><button type="button" id="v3-gamepad-defaults">DEFAULT MAP</button></div><p class="v3-gamepad-help">Select an action, then press the physical controller button to bind it. The left stick trims heading and target speed; the right stick controls depth. Mapping is saved on this browser.</p><div class="v3-gamepad-buttons"><button type="button" data-gamepad-map="left">TURN LEFT // D-PAD LEFT</button><button type="button" data-gamepad-map="right">TURN RIGHT // D-PAD RIGHT</button><button type="button" data-gamepad-map="up">ASCEND // Y / TRIANGLE</button><button type="button" data-gamepad-map="down">DESCEND // B / CIRCLE</button><button type="button" data-gamepad-map="slower">SPEED − // X / SQUARE</button><button type="button" data-gamepad-map="faster">SPEED + // A / CROSS</button></div><div class="v3-gamepad-axis-note">LEFT STICK X: HEADING · LEFT STICK Y: SPEED · RIGHT STICK Y: DEPTH</div></details><details id="v3-evidence" class="v3-panel v3-collapsible" aria-label="Unique historical artifacts"><summary class="v3-panel-title">UNIQUE ARTIFACTS // RECOVERY &amp; CUSTODY</summary><p>Each artifact exists once. Survey reveals it; acquisition loads that same physical item into an active submersible’s locked container. If its carrier loses it, it remains at the loss coordinates for recovery. Survey resets never respawn artifacts.</p><div id="v3-evidence-list" aria-live="polite"></div></details><div class="v3-foot" id="v3-status" role="status" aria-live="polite">LIVE TERRAIN VIEW // CONTROLS COMMAND THE EXISTING SIMULATION</div>';
document.body.appendChild(view);
function renderHistoricalEvidence(){var list=view.querySelector('#v3-evidence-list');if(!list)return;var records=window.vigilGetHistoricalEvidenceInventory?window.vigilGetHistoricalEvidenceInventory():[];list.innerHTML='';var counts={CARRIED:0,LOST:0,AT_SITE:0,UNDISCOVERED:0};records.forEach(function(record){counts[record.status]=(counts[record.status]||0)+1;var article=document.createElement('article');article.className='v3-evidence-item';var title=document.createElement('strong');title.textContent=record.title;article.appendChild(title);var meta=document.createElement('small');meta.textContent=record.category+' // ORIGINAL RECOVERY SITE: '+record.siteName;article.appendChild(meta);var state=document.createElement('div');state.className='v3-evidence-state';state.textContent=record.status+' // UNIQUE ITEM // NO RESPAWN';article.appendChild(state);if(record.status!=='UNDISCOVERED'){var summary=document.createElement('p');summary.textContent=record.summary;article.appendChild(summary);if(record.status==='CARRIED'){var custody=document.createElement('small');custody.textContent='LOCKED CONTAINER // CARRIER: '+record.carrierId;article.appendChild(custody);if(record.carrierId!=='UUV-01'){var capture=document.createElement('button');capture.type='button';capture.textContent='ATTEMPT HOSTILE CUSTODY CAPTURE WITH UUV-01';capture.addEventListener('click',function(){var result=window.vigilCaptureHistoricalEvidence(record.id,record.carrierId,'UUV-01');if(result&&result.ok){renderHistoricalEvidence();say('HOSTILE CUSTODY CAPTURED // UNIQUE ARTIFACT SECURED // '+record.title);}else{say('CAPTURE DENIED // '+(result&&result.reason||'UNKNOWN ERROR'));}});article.appendChild(capture);}}else{if(record.status==='LOST'){var lost=document.createElement('small');lost.textContent='LOST AT X '+Number(record.location.x).toFixed(4)+' / Y '+Number(record.location.y).toFixed(4)+' // RECOVERABLE IN PLACE';article.appendChild(lost);}var collect=document.createElement('button');collect.type='button';collect.textContent=record.status==='LOST'?'RECOVER FROM LOSS COORDINATES INTO UUV-01':'LOAD INTO UUV-01 LOCKED CONTAINER';collect.addEventListener('click',function(){var result=window.vigilCollectHistoricalEvidence(record.id,'UUV-01');if(result&&result.ok){renderHistoricalEvidence();say((record.status==='LOST'?'LOST ARTIFACT RECOVERED':'UNIQUE ARTIFACT SECURED')+' IN LOCKED CONTAINER // '+record.title);}else{say('ACQUISITION DENIED // '+(result&&result.reason||'UNKNOWN ERROR'));}});article.appendChild(collect);}}else{var hidden=document.createElement('p');hidden.textContent='Unlocated in the survey record. Scan '+record.siteName+' to reveal its existing physical instance.';article.appendChild(hidden);}});var status=view.querySelector('#v3-status');if(status)status.textContent='UNIQUE ARTIFACTS // '+counts.CARRIED+' IN LOCKED CONTAINERS // '+counts.LOST+' LOST IN PLACE // '+counts.AT_SITE+' AT RECOVERY SITES // '+counts.UNDISCOVERED+' NOT YET DISCOVERED';}
window.addEventListener('vigil:historical-evidence-updated',renderHistoricalEvidence);
renderHistoricalEvidence();
var canvas=view.querySelector('#vigil-3d-terrain'),ctx=canvas.getContext('2d'),heading=0,speed=0,depth=120,zoom=1,tilt=-.68,offset=0,anim=0,last=0,drag=null,active=false,cameraX=0,cameraY=0,lookPitch=0,pilotWorldPoint=null;
 var arm1={deployed:false,extension:.18,yaw:0,prongsOpen:false,gripping:false,laserOn:false,weldMode:false,gripLoad:0,emitterTemp:18},arm2={deployed:false,extension:.18,yaw:0,stabilized:false,sawOn:false,sawSpeed:.35,motorLoad:0,vibration:.02,bladeTemp:18};
var fpsTrack=view.querySelector('#v3-fps-compass-track'),fpsBearing=view.querySelector('#v3-fps-bearing'),fpsCardinal=view.querySelector('#v3-fps-cardinal');
var fpsTickMarkup='';for(var fd=-720;fd<=720;fd+=5){var norm=((fd%360)+360)%360,major=norm%30===0,dir=({0:'N',30:'NE',90:'E',120:'SE',180:'S',210:'SW',270:'W',300:'NW'})[norm]||'',deg=String(norm).padStart(3,'0');fpsTickMarkup+='<div class="v3-fps-tick'+(major?' major':'')+(dir?' cardinal':'')+'" style="left:'+(fd*8)+'px">'+(major?'<span>'+(dir?'<b>'+dir+'</b>':'')+'<em>'+deg+'</em></span>':'')+'</div>';}if(fpsTrack)fpsTrack.innerHTML=fpsTickMarkup;
function updateFpsCompass(){var h=((Math.round(heading)%360)+360)%360,dirs=['N','NE','E','SE','S','SW','W','NW'];if(fpsTrack)fpsTrack.style.transform='translateX('+(-h*8)+'px)';if(fpsBearing)fpsBearing.textContent=String(h).padStart(3,'0')+'°';if(fpsCardinal)fpsCardinal.textContent=dirs[Math.round(h/45)%8];}
